      ok((await call('POST', '/api/org/workroom/surveys', VW, { title: 'x', questions: [{ type: 'text', prompt: 'Hi' }] })).s === 403, 'a viewer cannot start a Workroom survey'); r = await call('POST', '/api/org/workroom/surveys', APPR, { title: 'Women on the plan', questions: [{ type: 'choice', prompt: 'Would you buy a plan that covers maternity?', options: ['Yes', 'No'], feeds: { param: 'market_women_pct', option: 'Yes' } }] }); ok(r.s === 201, 'any team member except a viewer can start a survey in the Workroom'); const g = r.j;
