    ok(rr.s === 200 && sl.layers === 100 && /^G28$/m.test(sl.gcode) && /^M104 S210$/m.test(sl.gcode) && (sl.gcode.match(/^;LAYER /gm) || []).length === 100 && sl.preview.length > 10, 'slicing a cube gives 100 layers of G-code with heating and a layer preview');
    const filVol = sl.filamentMm * Math.PI * 0.875 * 0.875; ok(filVol > 8000 * 0.2 && filVol < 8000 * 0.55 && sl.hours > 0.05, 'the plastic it lays down matches the volume and infill within reason');
    const ext = sl.gcode.split('\n').filter((l) => l.startsWith('G1') && l.includes(' X')).map((l) => ({ x: +l.match(/X([\d.\-]+)/)[1], y: +l.match(/Y([\d.\-]+)/)[1] })); ok(ext.length > 500 && ext.every((p) => p.x > 85 && p.x < 135 && p.y > 85 && p.y < 135), 'every move stays on the bed, centred, around the part');
    ok((await H('POST', '/studio/slice', { part: { name: 'x', type: 'shaft', params: { length: 300, diameter: 4, endDiameter: 3, endLength: 20 } }, settings: { layerHeight: 0.05 } })).s === 422, 'a slice over the layer limit is refused with advice');
    rr = await H('POST', '/studio/slice', { part: { name: 'Gear', type: 'spur_gear', params: { module: 1.5, teeth: 24, thickness: 6, bore: 5 } }, settings: { infillPct: 0 } }); ok(rr.s === 200 && rr.j.layers === 30, 'a gear slices, with no infill when you ask for none');
    // assets and scenarios
    const design = { ...cat.starter, name: 'Maker arm' }; rr = await H('POST', '/assets', { kind: 'hardware_design', name: 'Maker arm', data: design }); ok(rr.s === 201 && rr.j.kind === 'hardware_design', 'a design is saved in the library'); const aid = rr.j.id;
    ok((await H('POST', '/assets', { kind: 'hardware_design', name: 'x', data: { parts: [] } })).s === 422 && (await H('POST', '/assets', { kind: 'hardware_design', name: 'x', data: { parts: [{ id: 'a', name: 'a', type: 'spur_gear', params: { teeth: 2 } }] } })).s === 422 && (await H('POST', '/assets', { kind: 'hardware_design', name: 'x', data: { parts: [{ id: 'a', name: 'a', type: 'shaft', params: {} }, { id: 'a', name: 'b', type: 'shaft', params: {} }] } })).s === 422, 'designs with no parts, bad parameters or repeated ids are refused');
    rr = await H('POST', '/runs', { scenario: 'print_run', inputs: { hardware_design: { assetId: aid } }, params: { quantity: 20, printers: 2, failurePct: 10 } }); const pr = rr.j; ok(rr.s === 201 && pr.headline.unitCost > 5 && pr.headline.partsNotFitting === 0 && pr.result.parts.length === 6 && pr.result.printers === 2 && pr.result.partCount === 9, 'a print run costs the design: unit cost, hours, parts that do not fit');
    ok(Math.abs(pr.result.totals.cost - pr.result.perUnit.cost * 20) < 1, 'the batch cost is the unit cost times the quantity');
    const one = (await H('POST', '/runs', { scenario: 'print_run', inputs: { hardware_design: { assetId: aid } }, params: { quantity: 20, printers: 1, failurePct: 10 } })).j; ok(one.headline.daysToFinish > pr.headline.daysToFinish * 1.6, 'a second printer roughly halves the days to finish');
    rr = await H('POST', '/runs', { scenario: 'build_economics', inputs: { hardware_design: { assetId: aid } }, params: { price: 150 } }); const ec = rr.j; ok(rr.s === 201 && ec.result.rows.length === 7 && ec.result.bomPerUnit === 66 && ec.headline.marginPctAt100 < 60 && ec.result.rows[6].moulded < ec.result.rows[0].moulded, 'build economics gives unit cost across volumes, with moulding getting cheaper as tooling is spread');
